mkdir -p scratch/cyborgMedic && cat > scratch/cyborgMedic/check.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/cyborgMedic";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
console.log("min", box.min.toArray().map(v=>+v.toFixed(3)), "max", box.max.toArray().map(v=>+v.toFixed(3)));
let meshes=0, tris=0; const joints:string[]=[];
root.traverse((o:any)=>{ if(o.isMesh){meshes++; const g=o.geometry; tris += (g.index? g.index.count: g.attributes.position.count)/3;} if(o.isBone||o.type==="Group"||o.userData?.joint) joints.push(o.name);});
console.log({meshes,tris});
EOF
npx tsx scratch/cyborgMedic/check.ts 2>&1 | tail -30
